package javiertorres.amazonconbackend22settembre.controller;
import javiertorres.amazonconbackend22settembre.dto.AuthDtos.*; import javiertorres.amazonconbackend22settembre.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public AuthResponse register(@Valid @RequestBody RegisterRequest x){return service.register(x);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest x){return service.login(x);} @PostMapping("/logout") public void logout(){}}
